from pathlib import Path
import json,html,collections
r=Path(__file__).resolve().parents[1];c=json.loads((r/'game/data/catalog.json').read_text());esc=lambda x:html.escape(str(x));tags=dict(weapon='武器',food='料理',material='材料',artifact='圣遗物',gadget='小道具',summon='召唤物');quality=['普通','精良','稀有','史诗','传说'];effects=dict(energy='充能',stamina='耐力恢复',heal='治疗',regen='持续再生',rescue='急救',shield='护盾',burn='灼烧',poison='中毒',slow='减速',cleanse='净化',empower='强化',haste='加速',crit='暴击',extra='追击',lifesteal='吸血',fish='大鲔冲击',alchemy='质变',copy='记录',thorns='反伤',healstrike='海染泡沫',income='每轮额外摩拉',foodboost='相邻料理治疗',healboost='相邻治疗',armorboost='相邻护盾',weaponboost='相邻武器',summonboost='相邻召唤',coreboost='核心强化',burnboost='灼烧强化',poisonboost='中毒强化',luck='幸运收藏',summon='弦外协同')
head='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>提瓦特背包乱斗 R2.1 · 角色与物品手册</title><style>*{box-sizing:border-box}body{margin:0;background:#30203e;color:#f4e5c5;font:16px/1.6 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:32px 24px}h1{font-size:36px}h2{color:#d8b56b;margin-top:40px}a{color:#dbbc84}.roles{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#f2e3c2;color:#352746;border:3px solid #d8b56b;padding:14px}.card img{width:100%;height:280px;object-fit:contain}.card h3{margin:0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{border-bottom:1px solid #6b5869;text-align:left;padding:9px}th{background:#4c3855;position:sticky;top:0}input,select{padding:12px;background:#f2e3c2;color:#352746;border:2px solid #d8b56b;font-size:16px;margin:8px 8px 18px 0}input{width:320px;max-width:100%}.scroll{overflow:auto}p{max-width:1000px}.muted{color:#c4afc4}@media(max-width:800px){.roles{grid-template-columns:repeat(2,1fr)}.card img{height:200px}main{padding:20px 12px}h1{font-size:28px}}</style><main><h1>提瓦特 · 背包乱斗 R2.1</h1><p>8名冒险者 · 140件物品 · 34条配方 · 18轮参考成长曲线</p><p>选角 → 商店购买与背包整理 → 天赋／专精 → 匹配预演 → 自动对决 → 结算与合成 → 下一轮。标准10胜／5败，10胜后可选择生存至18轮；无尽模式之后继续沿用末轮经济与生命上限，失败5次结束。</p><p class="muted">这是改编玩法。名称来自原神物品与梗，数值、配方和角色技能为本Demo设计。对手是标注来源的电脑构筑或本地镜像，未接入在线玩家匹配。当前采用图元拟合立绘，以下展示对应PNG原图。</p><h2>冒险者</h2><div class="roles">'''
parts=[head]
for h in c['characters']:parts.append(f'<article class="card"><img loading="lazy" src="../portraits/{h["id"]}.png" onerror="this.onerror=null;this.src=\'./portraits/{h["id"]}.png\'" alt="{esc(h["name"])}"><h3>{esc(h["name"])}</h3><strong>{esc(h["role"])}</strong><p>{esc(h["desc"])}</p><small>专精：{esc("／".join(h["subclasses"]))}</small></article>')
parts.append('</div><h2>物品目录</h2><p>武器40 · 料理28 · 材料16 · 圣遗物24 · 小道具20 · 召唤物12。料理次数每场重置；储物物品不参战；相邻按共享边计算。支持拖放和放置预览，实际联动对象会高亮；配方追踪会标记商店材料并显示缺少项。</p><input id="search" placeholder="搜索名称或效果" aria-label="搜索物品"><select id="type" aria-label="物品类别"><option value="">所有类别</option>'+''.join(f'<option value="{k}">{v}</option>'for k,v in tags.items())+'</select><div class="scroll"><table><thead><tr><th>名称</th><th>类别</th><th>品质</th><th>格数</th><th>摩拉</th><th>出现轮次</th><th>伤害／间隔／耐力</th><th>效果</th></tr></thead><tbody id="items">')
for d in c['items']:
 stats=f'{d.get("damage","—")} / {d.get("cd",0)}秒 / {d.get("cost",0)}';effect=effects.get(d['effect'],'稳定攻击');parts.append(f'<tr data-tag="{d["tag"]}"><td>{esc(d["name"])}</td><td>{tags[d["tag"]]}</td><td>{quality[d["q"]-1]}</td><td>{d["w"]}×{d["h"]}</td><td>{d["price"]}</td><td>{d["minRound"]}+</td><td>{stats}</td><td>{effect}'+(f' · 每场{d["uses"]}次'if'uses'in d else'')+'</td></tr>')
parts.append('</tbody></table></div><h2>34条战后合成配方</h2><p>将材料放在背包内相邻；开启战后合成后在结算阶段尝试合成，无法容纳产物则保留原材料。</p><table><thead><tr><th>材料一</th><th>材料二</th><th>产物</th></tr></thead><tbody>')
by={d['id']:d['name']for d in c['items']}
for p in c['recipes']:parts.append('<tr>'+''.join(f'<td>{esc(by[p[k]])}</td>'for k in['a','b','out'])+'</tr>')
parts.append('</tbody></table><h2>成长与约束</h2><p>初始13摩拉与16格，4摩拉扩展4格，最大9×7格；商店5件，前4次刷新各1摩拉，此后2摩拉。第3和10轮选择天赋，第8轮选择角色专精。耐力上限5、每秒恢复1；17秒后疲劳逐步增强，避免无限治疗拖延。护盾上限为生命上限的80%，加速和暴击均有上限。</p><table><thead><tr><th>轮次</th><th>本轮摩拉</th><th>基础生命</th><th>节点</th></tr></thead><tbody>')
for i,(gold,hp)in enumerate(zip(c['economy']['gold'],c['economy']['hp']),1):parts.append(f'<tr><td>{i}</td><td>{gold}</td><td>{hp}</td><td>{"天赋"if i in[3,10]else"专精"if i==8 else"标准生存终点"if i==18 else""}</td></tr>')
parts.append('''</tbody></table><h2>匹配与平衡说明</h2><p>同轮次候选按本轮购物前的构筑指标筛选，结合近期表现，再以两个固定种子分步预演，选择接近的候选并保留适度波动；本轮购物和整理的收益不会被立即追加强敌抵消；双方共享规则，不临时修正敌人属性。预演接近度不等于承诺胜率，暴击与流派克制仍然有效。有限的电脑构筑筛查与核心对照测试用于迭代数值，尚需真实玩家长局测试。</p><h2>资料来源</h2><p><a href="https://store.steampowered.com/app/2427700/Backpack_Battles/">背包乱斗官方介绍</a> · <a href="https://wikiwiki.jp/bpb/includex引用リスト">固定经济／生命／稀有度曲线参考</a> · <a href="https://wikiwiki.jp/bpb/ゲームシステム">背包与商店系统参考</a> · <a href="https://wiki.biligame.com/ys/食物一览">原神料理</a> · <a href="https://wiki.biligame.com/ys/武器一览">原神武器</a> · <a href="https://wiki.biligame.com/ys/衔珠海皇">衔珠海皇</a> · <a href="https://wiki.biligame.com/ys/叁零式·便携营养袋">便携营养袋</a></p><p class="muted">成长曲线为明确冻结的参考版本，未声称与原作最新补丁完全一致。“应急食品立牌”为梗改编。模拟器来源：1475505/miliastra-beyond-simulator，GPL-3.0-only。</p></main><script>function filter(){const q=document.querySelector('#search').value.toLowerCase(),t=document.querySelector('#type').value;for(const r of document.querySelectorAll('#items tr'))r.hidden=(t&&r.dataset.tag!==t)||!r.textContent.toLowerCase().includes(q)}document.querySelector('#search').oninput=filter;document.querySelector('#type').onchange=filter;</script></html>''')
(r/'dist/downloads/catalog.html').write_text(''.join(parts))
